import { z } from "zod"

export type PlanId = "starter" | "studio" | "workshop"

export const PLANS: { id: PlanId; name: string; cents: number; blurb: string; notebooks: number; storageGb: number; seats: number }[] = [
  { id: "starter", name: "Starter", cents: 0, blurb: "One notebook, one pen, no rush.", notebooks: 3, storageGb: 1, seats: 1 },
  { id: "studio", name: "Studio", cents: 1200, blurb: "Ten notebooks and the good highlighters.", notebooks: 10, storageGb: 10, seats: 3 },
  { id: "workshop", name: "Workshop", cents: 3200, blurb: "A whole desk. Washi tape included.", notebooks: 100, storageGb: 100, seats: 15 },
]

export const money = (cents: number): string => `$${(cents / 100).toFixed(2)}`

export const DAYS_LEFT = 18
export const DAYS_IN_CYCLE = 30
export const RENEWS = "14 Oct"

export type PlanChange = { from: PlanId; to: PlanId; kind: "same" | "upgrade" | "downgrade"; today: number; monthly: number }

export function planChange(from: PlanId, to: PlanId): PlanChange {
  const a = PLANS.find((p) => p.id === from)!.cents
  const b = PLANS.find((p) => p.id === to)!.cents
  if (from === to) return { from, to, kind: "same", today: 0, monthly: b }
  if (b > a) return { from, to, kind: "upgrade", today: Math.round(((b - a) * DAYS_LEFT) / DAYS_IN_CYCLE), monthly: b }
  return { from, to, kind: "downgrade", today: 0, monthly: b }
}

export const USAGE = [
  { id: "notebooks", label: "Notebooks", used: 8, unit: "" },
  { id: "storage", label: "Storage", used: 8.4, unit: " GB" },
  { id: "seats", label: "People on the desk", used: 3, unit: "" },
] as const

export type Invoice = { number: string; date: string; lines: { name: string; price: string }[]; total: string; paidWith: string }

export const INVOICES: Invoice[] = [
  { number: "2026-0009", date: "14 Sep 2026", lines: [{ name: "Studio plan, September", price: "12.00" }, { name: "Extra storage, 5 GB", price: "2.50" }], total: "14.50", paidWith: "Visa 4242" },
  { number: "2026-0008", date: "14 Aug 2026", lines: [{ name: "Studio plan, August", price: "12.00" }], total: "12.00", paidWith: "Visa 4242" },
  { number: "2026-0007", date: "14 Jul 2026", lines: [{ name: "Studio plan, July", price: "12.00" }, { name: "Washi tape pack, sticker sheet", price: "6.00" }], total: "18.00", paidWith: "Visa 4242" },
  { number: "2026-0006", date: "14 Jun 2026", lines: [{ name: "Studio plan, June", price: "12.00" }], total: "12.00", paidWith: "Visa 4242" },
  { number: "2026-0005", date: "14 May 2026", lines: [{ name: "Studio plan, May", price: "12.00" }], total: "12.00", paidWith: "Visa 4242" },
  { number: "2026-0004", date: "14 Apr 2026", lines: [{ name: "Starter to Studio, part month", price: "7.20" }], total: "7.20", paidWith: "Visa 4242" },
]

export function luhn(digits: string): boolean {
  let sum = 0
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i])
    if (i % 2 === 1) {
      d *= 2
      if (d > 9) d -= 9
    }
    sum += d
  }
  return digits.length > 0 && sum % 10 === 0
}

export function cardBrand(digits: string): "Visa" | "Mastercard" | "Amex" | "Card" {
  if (/^4/.test(digits)) return "Visa"
  if (/^(5[1-5]|2[2-7])/.test(digits)) return "Mastercard"
  if (/^3[47]/.test(digits)) return "Amex"
  return "Card"
}

export function formatCardNumber(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 19)
  if (/^3[47]/.test(d)) return [d.slice(0, 4), d.slice(4, 10), d.slice(10, 15)].filter(Boolean).join(" ")
  return d.replace(/(.{4})/g, "$1 ").trim()
}

export function formatExpiry(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 4)
  if (d.length === 1 && Number(d) > 1) return `0${d}/`
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d
}

export type Month = { year: number; month: number }

export function currentMonth(): Month {
  // lint-house-disable-next-line render-time
  const now = new Date()
  return { year: now.getFullYear(), month: now.getMonth() + 1 }
}

export function makeCardSchema(today: Month) {
  return z.object({
    name: z.string().trim().min(2, "Type the name as it is printed on the card."),
    number: z
      .string()
      .refine((v) => /^\d{13,19}$/.test(v.replace(/\s/g, "")), "A card number has 13 to 19 digits.")
      .refine((v) => luhn(v.replace(/\s/g, "")), "That number does not add up. Check each digit."),
    expiry: z
      .string()
      .regex(/^(0[1-9]|1[0-2])\/\d{2}$/, "Write it as MM/YY, like 08/28.")
      .refine((v) => {
        const [m, y] = v.split("/").map(Number)
        return 2000 + y > today.year || (2000 + y === today.year && m >= today.month)
      }, "That card has expired."),
    cvc: z.string().regex(/^\d{3,4}$/, "The security code is 3 or 4 digits."),
  })
}

export type CardValues = z.infer<ReturnType<typeof makeCardSchema>>

export const detailsSchema = z.object({
  email: z.email("Enter an address like billing@notes.dev."),
  company: z.string().trim().max(60, "Keep the company name to 60 characters."),
  taxId: z.string().trim().regex(/^([A-Za-z]{2}[A-Za-z0-9]{8,12})?$/, "A VAT number starts with two letters, like PT123456789."),
})

export type DetailsValues = z.infer<typeof detailsSchema>

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Receipt, ReceiptFooter, ReceiptHeader, ReceiptLine, ReceiptLines, ReceiptTotal } from "@/components/ui/receipt"
import type { Invoice } from "@/components/blocks/settings-billing/components/settings-billing-data"

export function SettingsBillingInvoices({ invoices, onDownload }: { invoices: Invoice[]; onDownload?: (invoice: Invoice) => void }) {
  const [all, setAll] = React.useState(false)
  const shown = all ? invoices : invoices.slice(0, 3)
  return (
    <div className="grid gap-6">
      <ul aria-label="Invoices" className="grid grid-cols-[repeat(auto-fill,minmax(min(100%,16rem),18rem))] gap-x-6 gap-y-10">
        {shown.map((inv, i) => (
          <li key={inv.number} className="grid w-full content-between justify-items-center gap-3">
            <Receipt as="article" seed={`invoice-${inv.number}`} aria-label={`Invoice ${inv.number}`} ends={i % 2 ? "perf" : "zig"} className="w-full max-w-72">
              <ReceiptHeader>
                <span>Looseleaf</span>
                <span>Invoice {inv.number}</span>
                <span>{inv.date}</span>
              </ReceiptHeader>
              <ReceiptLines>
                {inv.lines.map((l) => (
                  <ReceiptLine key={l.name} price={l.price}>
                    {l.name}
                  </ReceiptLine>
                ))}
              </ReceiptLines>
              <ReceiptTotal circled={i === 0}>{inv.total}</ReceiptTotal>
              <ReceiptFooter>paid by {inv.paidWith} - thank you</ReceiptFooter>
            </Receipt>
            <Button variant="outline" size="sm" onClick={() => onDownload?.(inv)} aria-label={`Download invoice ${inv.number}`}>
              <Icon name="download" />
              Download PDF
            </Button>
          </li>
        ))}
      </ul>
      {invoices.length > 3 ? (
        <Button variant="link" className="justify-self-start" aria-expanded={all} onClick={() => setAll((v) => !v)}>
          {all ? "Show fewer invoices" : `Show ${invoices.length - 3} older invoices`}
        </Button>
      ) : null}
    </div>
  )
}

"use client"

import * as React from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Field, FieldContent, FieldDescription, FieldLabel, FieldTitle } from "@/components/ui/field"
import { Icon } from "@/components/ui/icon"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Ticket, TicketBody, TicketDescription, TicketNumber, TicketStub, TicketTitle } from "@/components/ui/ticket"
import { DAYS_LEFT, PLANS, RENEWS, USAGE, money, planChange, type PlanId } from "@/components/blocks/settings-billing/components/settings-billing-data"

export const limitOf = (plan: PlanId, key: (typeof USAGE)[number]["id"]): number => {
  const p = PLANS.find((x) => x.id === plan)!
  return key === "notebooks" ? p.notebooks : key === "storage" ? p.storageGb : p.seats
}

export function SettingsBillingPlan({ current, scheduled, onChange }: { current: PlanId; scheduled?: PlanId; onChange: (plan: PlanId) => void }) {
  const [picked, setPicked] = React.useState<PlanId>(current)
  const [done, setDone] = React.useState("")
  const uid = React.useId()
  const plan = PLANS.find((p) => p.id === current)!
  const next = scheduled ? PLANS.find((p) => p.id === scheduled) : undefined
  const target = PLANS.find((p) => p.id === picked)!
  const change = planChange(current, picked)
  const over = USAGE.filter((u) => u.used > limitOf(picked, u.id)).map((u) => `${u.label.toLowerCase()} (${u.used}${u.unit} of ${limitOf(picked, u.id)}${u.unit})`)

  return (
    <div className="grid gap-6">
      <div role="group" aria-label={`Your plan: ${plan.name}`}>
        <Ticket stock="kraft" seed="plan-ticket" size={[420, 124]} className="w-full max-w-md">
          <TicketBody>
            <TicketTitle>{plan.name} plan</TicketTitle>
            <TicketDescription>
              <span className="whitespace-nowrap">{money(plan.cents)} a month ·</span> <span className="whitespace-nowrap">renews {RENEWS}</span>
            </TicketDescription>
            <TicketNumber>No. 0042</TicketNumber>
          </TicketBody>
          <TicketStub>
            <span className="font-type text-xs">Admit</span>
            <span className="font-script text-4xl leading-none font-bold">1</span>
          </TicketStub>
        </Ticket>
      </div>

      {next ? (
        <p className="flex flex-wrap items-center gap-x-3 text-sm">
          <span>
            Moving to <b>{next.name}</b> on {RENEWS}.
          </span>
          <Button
            type="button"
            variant="link"
            size="sm"
            onClick={() => {
              onChange(current)
              setPicked(current)
              setDone(`Staying on ${plan.name}.`)
            }}
          >
            Keep {plan.name}
          </Button>
        </p>
      ) : null}

      <RadioGroup
        value={picked}
        onValueChange={(v) => {
          setPicked(v as PlanId)
          setDone("")
        }}
        aria-label="Plan"
        className="gap-3 @4xl/settings:grid-cols-3"
      >
        {PLANS.map((p) => (
          <FieldLabel key={p.id} htmlFor={`${uid}-plan-${p.id}`}>
            <Field orientation="horizontal">
              <FieldContent>
                <FieldTitle className="flex-wrap">
                  {p.name}
                  {p.id === current ? (
                    <Badge size="sm" variant="secondary">
                      Current
                    </Badge>
                  ) : null}
                </FieldTitle>
                <FieldDescription>
                  <span className="ll-num font-bold text-foreground">{p.cents ? `${money(p.cents)} a month` : "Free"}</span>
                  <br />
                  {p.blurb}
                </FieldDescription>
              </FieldContent>
              <RadioGroupItem value={p.id} id={`${uid}-plan-${p.id}`} />
            </Field>
          </FieldLabel>
        ))}
      </RadioGroup>

      {change.kind === "upgrade" ? (
        <Alert variant="info">
          <Icon name="info" />
          <AlertTitle>Move up to {target.name}</AlertTitle>
          <AlertDescription>
            From {RENEWS} you will pay {money(change.monthly)} a month. Today we charge {money(change.today)} for the {DAYS_LEFT} days left in this month, and nothing more.
          </AlertDescription>
        </Alert>
      ) : null}
      {change.kind === "downgrade" ? (
        <Alert variant="warning">
          <Icon name="triangle-alert" />
          <AlertTitle>Move down to {target.name}</AlertTitle>
          <AlertDescription>
            You keep {plan.name} until {RENEWS}, then pay {change.monthly ? `${money(change.monthly)} a month` : "nothing"}. Nothing is charged today.
            {over.length ? ` You use more than ${target.name} holds: ${over.join(", ")}. The extra stays readable but cannot be edited.` : ""}
          </AlertDescription>
        </Alert>
      ) : null}

      <div className="flex flex-wrap items-center gap-3">
        <Button
          type="button"
          disabled={change.kind === "same"}
          onClick={() => {
            onChange(picked)
            setDone(change.kind === "upgrade" ? `You are on ${target.name} now.` : `Done. ${target.name} starts on ${RENEWS}.`)
            if (change.kind === "upgrade") setPicked(picked)
          }}
        >
          {change.kind === "same" ? "Pick another plan" : `Switch to ${target.name}`}
        </Button>
        <p role="status" className="text-sm font-bold text-green">
          {done}
        </p>
      </div>
    </div>
  )
}
